package bookstore

// Cost returns the total cost, in cents, of the books in the basket,
// grouping them so that the shop's discounts are maximized.
//
// One copy of any book costs 800 cents. A group of distinct titles
// (each title at most once per group) gets a discount that grows with
// the group size:
//
//	1 book:  800 (no discount)
//	2 books: 1520 (5% off)
//	3 books: 2160 (10% off)
//	4 books: 2560 (20% off)
//	5 books: 3000 (25% off)
//
// Books are 1-5, one for each title in the series.
func Cost(books []int) int {
	var counts [5]int
	for _, book := range books {
		counts[book-1]++
	}
	return minCost(counts, make(map[[5]int]int))
}

// price[size] is the cost, in cents, of a group of `size` distinct books.
var price = [6]int{0, 800, 1520, 2160, 2560, 3000}

// groups enumerates all 31 non-empty subsets of the five titles,
// as {bitmask, size}.
var groups = func() [][2]int {
	var gs [][2]int
	for mask := 1; mask < 32; mask++ {
		size := 0
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				size++
			}
		}
		gs = append(gs, [2]int{mask, size})
	}
	return gs
}()

// minCost returns the minimum cost of buying the books described by
// counts. It considers every valid first group (a set of distinct
// titles that still have copies left) and memoizes the result, so
// every subproblem is solved exactly once.
func minCost(counts [5]int, memo map[[5]int]int) int {
	if counts == ([5]int{}) {
		return 0
	}
	if cost, ok := memo[counts]; ok {
		return cost
	}

	best := -1
	for _, g := range groups {
		mask, size := g[0], g[1]

		// The group may only contain titles we still have.
		available := true
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 && counts[i] == 0 {
				available = false
				break
			}
		}
		if !available {
			continue
		}

		next := counts
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				next[i]--
			}
		}

		cost := price[size] + minCost(next, memo)
		if best < 0 || cost < best {
			best = cost
		}
	}

	memo[counts] = best
	return best
}

